import{_ as r,o as t,c as s,ah as i}from"./chunks/framework.BsNNkeaH.js";const g=JSON.parse('{"title":"Bulletins et cahier de textes","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/enseignant/bulletins-et-cahier-texte.md","filePath":"src/guide/enseignant/bulletins-et-cahier-texte.md"}'),n={name:"guide/enseignant/bulletins-et-cahier-texte.md"};function a(o,e,l,c,u,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="bulletins-et-cahier-de-textes" tabindex="-1">Bulletins et cahier de textes <a class="header-anchor" href="#bulletins-et-cahier-de-textes" aria-label="Permalink to &quot;Bulletins et cahier de textes&quot;">​</a></h1><p>Cette page couvre deux tâches distinctes : rédiger les appréciations qui apparaîtront sur les bulletins de vos élèves, et tenir le cahier de textes qui trace le contenu de vos séances et les devoirs donnés.</p><h2 id="rediger-les-appreciations-par-matiere" tabindex="-1">Rédiger les appréciations par matière <a class="header-anchor" href="#rediger-les-appreciations-par-matiere" aria-label="Permalink to &quot;Rédiger les appréciations par matière&quot;">​</a></h2><p>Pour chacune de vos affectations classe/matière, vous pouvez saisir une appréciation par élève pour une période scolaire donnée.</p><ol><li>Depuis la liste des <strong>Évaluations</strong>, cliquez sur <strong>Bulletins</strong> sur la ligne d&#39;une évaluation de la classe et de la matière concernées.</li><li>Choisissez la <strong>période scolaire</strong> dans le sélecteur en haut de page.</li><li>Pour chaque élève, saisissez son <strong>Appréciation</strong> dans le champ de texte (facultatif).</li><li>Cliquez sur <strong>Enregistrer</strong> — toutes les appréciations de la liste sont enregistrées en une fois.</li></ol><h2 id="rediger-l-appreciation-generale-de-fin-de-periode-professeur-principal" tabindex="-1">Rédiger l&#39;appréciation générale de fin de période (professeur principal) <a class="header-anchor" href="#rediger-l-appreciation-generale-de-fin-de-periode-professeur-principal" aria-label="Permalink to &quot;Rédiger l&#39;appréciation générale de fin de période (professeur principal)&quot;">​</a></h2><p>Si vous êtes professeur principal d&#39;une classe, vous saisissez en plus une appréciation générale de fin de période, distincte des appréciations par matière.</p><ol><li>Ouvrez <strong>Enseignement → Ma classe</strong>, puis cliquez sur <strong>Appréciations de fin de période</strong> à côté de la classe concernée.</li><li>Choisissez la <strong>période scolaire</strong> dans le sélecteur en haut de page.</li><li>Pour chaque élève, renseignez l&#39;<strong>Appréciation générale</strong> et la <strong>Conduite</strong>, et cochez si besoin une ou plusieurs mentions : <strong>Félicitations</strong>, <strong>Compliments</strong>, <strong>Encouragements</strong>, <strong>Alerte travail</strong>, <strong>Alerte conduite</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><h2 id="tenir-le-cahier-de-textes" tabindex="-1">Tenir le cahier de textes <a class="header-anchor" href="#tenir-le-cahier-de-textes" aria-label="Permalink to &quot;Tenir le cahier de textes&quot;">​</a></h2><p>Le cahier de textes trace, séance par séance, ce qui a été fait en cours et les devoirs donnés, pour toutes vos affectations classe/matière.</p><ol><li>Ouvrez <strong>Enseignement → Cahier de texte</strong>, puis cliquez sur <strong>Nouvelle entrée</strong>.</li><li>Choisissez la <strong>Classe</strong> et la <strong>Matière</strong>, puis renseignez la <strong>Date</strong>.</li><li>Décrivez le <strong>Contenu du cours</strong> (obligatoire) et, si besoin, les <strong>Devoirs</strong> donnés.</li><li>Joignez éventuellement un <strong>Document</strong> (PDF, JPG ou PNG).</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>La liste des entrées se filtre par mot-clé (recherche dans le contenu) ou par classe, et affiche pour chacune sa date, sa classe, sa matière, son contenu et ses devoirs. Depuis cette liste :</p><ul><li>le bouton <strong>Document</strong> télécharge la pièce jointe si une entrée en a une ;</li><li><strong>Modifier</strong> rouvre l&#39;entrée pour la corriger (vous pouvez y remplacer ou retirer le document joint) ;</li><li><strong>Supprimer</strong> l&#39;efface définitivement, après confirmation — action irréversible.</li></ul>',13)])])}const h=r(n,[["render",a]]);export{g as __pageData,h as default};
